-- Sevillana: a real Feria de Abril outfit, not a short party dress (product owner). The faithful model follows clothing detail better.
update public.personalities set image_prompt = 'Dress the pet in an authentic traje de flamenca from the Feria de Abril in Seville: a long, fitted red dress with white polka dots that flares into several tiers of big ruffles (volantes) down to the ground, ruffled sleeves at the elbows, a fringed embroidered manila shawl (mantón) in cream with coloured flowers over the shoulders, a big red flower and a peineta comb on top of its head, and large hoop earrings hanging by its ears; keeping its natural face with no make-up. Place it in a sunny Andalusian courtyard with colourful tiles, white walls and pots of red geraniums, in a proud flamenco pose.', outfit_prompt = 'an authentic long red Feria de Abril flamenca dress with white polka dots and several tiers of big ruffles down to the ground, a fringed embroidered manila shawl, a big red flower and a peineta comb on its head, no make-up, proud flamenco pose', image_prompt_male = 'Dress the pet in an authentic Andalusian traje corto: a short, fitted black jacket (chaquetilla) ending at the waist, a crisp white shirt with a high collar, high-waisted grey striped trousers with a red sash (fajín), and a flat-brimmed black sombrero cordobés. Place it in a sunny Andalusian courtyard with colourful tiles, white walls and pots of red geraniums, posing proudly.', outfit_prompt_male = 'an authentic Andalusian traje corto: short fitted black chaquetilla, white high-collared shirt, high-waisted grey striped trousers, red sash and a flat-brimmed black sombrero cordobés, proud pose' where id = 'es-sevillana';

-- Alentejano: long capote, beret instead of a hat and a long straw in the mouth (product owner).
update public.personalities set image_prompt = 'Dress the pet as a traditional Alentejo countryman: a long brown wool capote (a heavy shepherd''s cape-coat with a sheepskin collar) down to its knees, a flat black wool beret (boina) on its head, a red neckerchief, and a long thin dry stalk of straw held in the corner of its mouth. Place it resting calmly in the shade of a cork oak on the golden Alentejo plain on a hot summer afternoon, a whitewashed farmhouse with a blue stripe in the distance, a clay water jug beside it. Peaceful, sunny, unhurried.', outfit_prompt = 'a long brown wool capote cape-coat with a sheepskin collar, a flat black wool beret, a red neckerchief and a long thin stalk of straw in the corner of its mouth, with a calm, unhurried, wise look' where id = 'pt-alentejo';

-- Modes can ask for the faithful image model too (it follows detailed outfits better): the Sevillana dress.
alter table public.personalities add column if not exists faithful boolean not null default false;
update public.personalities set faithful = true where id = 'es-sevillana';
update public.personalities set image_prompt = replace(image_prompt, 'a long thin dry stalk of straw held in the corner of its mouth', 'a long golden stalk of straw, clearly visible, held in the corner of its mouth and sticking out to the side'),
  outfit_prompt = replace(outfit_prompt, 'a long thin stalk of straw in the corner of its mouth', 'a long golden stalk of straw clearly sticking out of the corner of its mouth')
where id = 'pt-alentejo';
